<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Hash;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Str;
use App\Services\Store;
use App\Services\Money;
use App\Services\Backup;
use App\Models\User;
class StoreTest extends TestCase {
 use RefreshDatabase;
 private Store $store;private int $variant;
 protected function setUp():void {parent::setUp();config(['maro.gateway'=>'disabled','maro.live'=>false]);$this->seed(\Database\Seeders\DemoSeeder::class);$this->store=app(Store::class);$this->variant=DB::table('product_variants')->value('id');}
 private function input(int $qty=1,string $owner='session-one'):array {$d=['name'=>'خریدار آزمایشی','mobile'=>'09120000000','province'=>'اصفهان','city'=>'اصفهان','address'=>'نشانی آزمایشی برای تست سیستم','postal'=>'1234567890','email'=>null,'note'=>null,'items'=>[['variant_id'=>$this->variant,'quantity'=>$qty]],'idempotency_key'=>(string)Str::uuid()];$d['quote_signature']=$this->store->signature($this->store->quote($d),$owner);return $d;}
 private function pending(int $qty=1):array {$r=$this->store->start($this->input($qty),'session-one');$o=DB::table('orders')->latest('id')->first();$a=DB::table('payment_attempts')->where('order_id',$o->id)->first();DB::table('payment_attempts')->where('id',$a->id)->update(['authority'=>'A-'.$a->id,'status'=>'pending']);DB::table('inventory_reservations')->where('order_id',$o->id)->update(['status'=>'active']);return [$o,$a,$r];}
 private function verified(object $o,object $a):array{return ['status'=>'verified','amount'=>$o->total,'authority'=>'A-'.$a->id,'reference'=>'R-'.$a->id];}
 public function test_catalog_and_local_frontend():void {$this->get('/')->assertOk()->assertSee('assets/app.js');$this->getJson('/api/catalog')->assertOk()->assertJsonCount(2,'products');}
 public function test_price_tampering_is_ignored():void {$d=$this->input();$d['items'][0]['price']=1;$d['total']=1;$r=$this->store->start($d,'session-one');$o=DB::table('orders')->first();$this->assertSame(1850000,(int)$o->subtotal);$this->assertSame(2500000,(int)$o->total);$this->assertNotEmpty($r['token']);}
 public function test_changed_price_requires_review():void {$d=$this->input();DB::table('product_variants')->where('id',$this->variant)->update(['price'=>2000000]);$this->expectException(\Illuminate\Validation\ValidationException::class);$this->store->start($d,'session-one');}
 public function test_duplicate_checkout_is_idempotent_and_owner_bound():void {$d=$this->input();$a=$this->store->start($d,'session-one');$b=$this->store->start($d,'session-one');$this->assertSame($a['token'],$b['token']);$this->assertDatabaseCount('orders',1);$this->assertDatabaseCount('payment_attempts',1);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$this->store->start($d,'different-session');}
 public function test_last_unit_cannot_be_reserved_twice():void {DB::table('product_variants')->where('id',$this->variant)->update(['stock'=>1]);$this->pending();$this->expectException(\Illuminate\Validation\ValidationException::class);$this->store->quote(['items'=>[['variant_id'=>$this->variant,'quantity'=>1]],'province'=>'اصفهان'],true);}
 public function test_duplicate_callback_consumes_stock_once():void {[$o,$a]=$this->pending(2);$this->assertSame('verified',$this->store->settle($a->id,$this->verified($o,$a)));$this->store->settle($a->id,$this->verified($o,$a));$this->assertSame(3,(int)DB::table('product_variants')->find($this->variant)->stock);$this->assertDatabaseCount('stock_movements',1);$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'paid']);}
 public function test_untrusted_callback_status_is_not_payment():void {[$o,$a]=$this->pending();$this->get('/payment/callback?Authority=A-'.$a->id.'&Status=OK')->assertOk();$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'review']);$this->assertDatabaseCount('stock_movements',0);}
 public function test_wrong_amount_or_authority_does_not_mark_paid():void {[$o,$a]=$this->pending();$result=$this->verified($o,$a);$result['amount']=1;$this->assertSame('unknown',$this->store->settle($a->id,$result));$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'review']);$result=$this->verified($o,$a);$result['authority']='wrong';$this->assertSame('unknown',$this->store->settle($a->id,$result));}
 public function test_failed_payment_releases_reservation():void {[$o,$a]=$this->pending();$this->store->settle($a->id,['status'=>'failed']);$this->assertDatabaseHas('inventory_reservations',['order_id'=>$o->id,'status'=>'released']);$this->assertSame(5,(int)DB::table('product_variants')->find($this->variant)->stock);}
 public function test_expired_reservation_is_released():void {[$o]=$this->pending();DB::table('inventory_reservations')->where('order_id',$o->id)->update(['expires_at'=>now()->subMinute()]);$this->assertSame(1,$this->store->expire());$this->assertSame(5,$this->store->available(DB::table('product_variants')->find($this->variant)));}
 public function test_late_verified_payment_without_stock_goes_to_exception():void {[$o,$a]=$this->pending();DB::table('inventory_reservations')->where('order_id',$o->id)->update(['status'=>'expired']);DB::table('product_variants')->where('id',$this->variant)->update(['stock'=>0]);$this->assertSame('paid_exception',$this->store->settle($a->id,$this->verified($o,$a)));$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'paid_exception']);$this->assertDatabaseCount('stock_movements',0);}
 public function test_late_payment_with_stock_succeeds():void {[$o,$a]=$this->pending();DB::table('inventory_reservations')->where('order_id',$o->id)->update(['status'=>'expired']);$this->store->settle($a->id,$this->verified($o,$a));$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'paid']);}
 public function test_shipping_snapshot_does_not_change():void {$this->store->start($this->input(),'session-one');DB::table('shipping_rules')->update(['amount'=>999000]);$this->assertSame(650000,(int)DB::table('orders')->first()->shipping);}
 public function test_tracking_token_and_privacy():void {$r=$this->store->start($this->input(),'session-one');$this->postJson('/api/track',['token'=>$r['token']])->assertOk()->assertJsonMissingPath('mobile')->assertJsonMissingPath('address')->assertJsonMissingPath('token_hash');$this->postJson('/api/track',['token'=>str_repeat('a',64)])->assertNotFound();$this->postJson('/api/track',['number'=>'1','mobile'=>'09120000000'])->assertUnprocessable();}
 public function test_admin_requires_authentication():void {$this->getJson('/api/admin/products')->assertForbidden();$this->getJson('/api/admin/orders')->assertForbidden();$this->postJson('/api/admin/products',[])->assertForbidden();}
 public function test_guest_digits_normalized_and_invalid_quantity_rejected():void {$d=$this->input();$d['mobile']='۰۹۱۲۰۰۰۰۰۰۰';$d['postal']='۱۲۳۴۵۶۷۸۹۰';$d['items'][0]['quantity']=-1;$this->postJson('/api/quote',$d)->assertUnprocessable();}
 private function admin():User {$u=User::factory()->create();DB::table('users')->where('id',$u->id)->update(['is_admin'=>true]);return $u->fresh();}
 public function test_admin_can_create_variant_upload_publish_and_audit():void {Storage::fake('local');$this->actingAs($this->admin());$response=$this->post('/api/admin/products',['name'=>'محصول تست','category'=>'فانتزی','description'=>'توضیح','status'=>'published','featured'=>'1','reason'=>'اولین موجودی','variants'=>json_encode([['color'=>'سبز','size'=>'اندازه واقعی تست','price'=>1000000,'stock'=>3,'sku'=>'TEST-NEW']]),'images'=>[UploadedFile::fake()->image('sock.jpg',640,480)]],['Accept'=>'application/json']);$response->assertOk();$id=$response->json('id');$this->assertDatabaseHas('products',['id'=>$id,'status'=>'published']);$image=DB::table('product_images')->where('product_id',$id)->first();$this->get('/media/'.$image->id)->assertOk()->assertHeader('Content-Type','image/webp');$this->assertDatabaseHas('audit_logs',['event'=>'product.saved']);$this->assertDatabaseHas('stock_movements',['reason'=>'اولین موجودی','quantity'=>3]);}
 public function test_malicious_upload_rejected():void {$this->actingAs($this->admin());$this->post('/api/admin/products',['name'=>'bad','category'=>'test','status'=>'draft','featured'=>'0','reason'=>'test','variants'=>json_encode([['color'=>'red','size'=>'A','price'=>1000,'stock'=>1,'sku'=>'BAD']]),'images'=>[UploadedFile::fake()->createWithContent('shell.jpg','<?php system($_GET["x"]);')]],['Accept'=>'application/json'])->assertUnprocessable();}
 public function test_unpaid_order_cannot_be_shipped():void {[$o]=$this->pending();$this->actingAs($this->admin())->postJson('/api/admin/orders/'.$o->id.'/shipment',['status'=>'shipped','carrier'=>'پست','tracking_code'=>'test','shipped_at'=>now()->toDateString()])->assertUnprocessable();}
 public function test_money_conversion_uses_integers():void {$this->assertSame(123450,Money::toToman(1234500));$this->assertSame(1234500,Money::toRial(123450));$this->assertSame(1234500,Money::gateway(1234500));$this->expectException(\InvalidArgumentException::class);Money::toToman(12345);}
 public function test_backup_roundtrip_in_empty_database():void {config(['maro.backup_dir'=>storage_path('framework/testing-backups')]);$this->store->start($this->input(),'session-one');$before=DB::table('orders')->first();$backup=app(Backup::class);$file=$backup->create();$this->assertStringNotContainsString('09120000000',file_get_contents($file));DB::statement('PRAGMA foreign_keys=OFF');foreach(array_reverse(Backup::TABLES)as $t)DB::table($t)->delete();DB::statement('PRAGMA foreign_keys=ON');$result=$backup->restore($file);$this->assertSame(1,$result['orders']);$this->assertSame($before->token_hash,DB::table('orders')->first()->token_hash);$this->assertSame($before->total,DB::table('orders')->first()->total);unlink($file);}
 public function test_live_mode_rejects_demo_products():void {$d=$this->input();config(['maro.live'=>true]);$this->expectException(\Illuminate\Validation\ValidationException::class);$this->store->quote($d);}

 public function test_retry_does_not_duplicate_order():void {[$o,$a,$r]=$this->pending();$this->store->settle($a->id,['status'=>'failed']);$this->store->retry($r['token']);$this->assertDatabaseCount('orders',1);$this->assertDatabaseCount('payment_attempts',2);}
 public function test_unknown_payment_cannot_be_retried():void {[$o,$a,$r]=$this->pending();$this->store->settle($a->id,['status'=>'unknown']);$this->expectException(\Illuminate\Validation\ValidationException::class);$this->store->retry($r['token']);}
 public function test_repeat_late_callback_keeps_exception_visible():void {[$o,$a]=$this->pending();DB::table('product_variants')->where('id',$this->variant)->update(['stock'=>0]);$this->store->settle($a->id,$this->verified($o,$a));$this->assertSame('paid_exception',$this->store->reconcile($a->id));}
 public function test_settings_content_and_server_validation():void {$this->actingAs($this->admin())->putJson('/api/admin/settings',['about'=>'مارو','shipping'=>650000,'free_above'=>null,'contact'=>'تماس تست','banner'=>'تیتر تست'])->assertOk();$this->getJson('/api/catalog')->assertJsonPath('settings.contact','تماس تست');$this->putJson('/api/admin/settings',['about'=>'مارو','shipping'=>1,'free_above'=>null])->assertUnprocessable();}
 public function test_csrf_is_required_outside_test_bypass():void {$this->app['env']='local';$this->postJson('/api/admin/login',['email'=>'owner@example.test','password'=>'bad'])->assertStatus(419);}

 public function test_stale_admin_stock_cannot_overwrite_completed_sale():void {
  $v=DB::table('product_variants')->find($this->variant);[$o,$a]=$this->pending();$this->store->settle($a->id,$this->verified($o,$a));$this->actingAs($this->admin());
  $this->post('/api/admin/products/'.$v->product_id,['name'=>'محصول','category'=>'فانتزی','description'=>'','status'=>'published','featured'=>'0','reason'=>'ذخیره فرم قدیمی','variants'=>json_encode([['id'=>$v->id,'revision'=>0,'color'=>$v->color,'size'=>$v->size,'price'=>$v->price,'stock'=>5,'sku'=>$v->sku]])],['Accept'=>'application/json'])->assertUnprocessable();
  $this->assertSame(4,(int)DB::table('product_variants')->find($v->id)->stock);$this->assertSame(1,(int)DB::table('product_variants')->find($v->id)->revision);
 }
 public function test_current_revision_allows_audited_stock_change():void {
  $v=DB::table('product_variants')->find($this->variant);$this->actingAs($this->admin());$this->post('/api/admin/products/'.$v->product_id,['name'=>'محصول','category'=>'فانتزی','description'=>'','status'=>'published','featured'=>'0','reason'=>'ورود بار','variants'=>json_encode([['id'=>$v->id,'revision'=>0,'color'=>$v->color,'size'=>$v->size,'price'=>$v->price,'stock'=>7,'sku'=>$v->sku]])],['Accept'=>'application/json'])->assertOk();$this->assertSame(7,(int)DB::table('product_variants')->find($v->id)->stock);$this->assertDatabaseHas('stock_movements',['variant_id'=>$v->id,'quantity'=>2,'reason'=>'ورود بار']);
 }
 public function test_malformed_array_inputs_are_validation_errors():void {
  $d=$this->input();$d['mobile']=['invalid'];$this->postJson('/api/checkout',$d)->assertUnprocessable();$this->actingAs($this->admin())->postJson('/api/admin/products',['variants'=>['invalid']])->assertUnprocessable();
 }
 public function test_unknown_old_attempt_cannot_downgrade_paid_order():void {
  [$o,$a]=$this->pending();$this->store->settle($a->id,$this->verified($o,$a));$id=DB::table('payment_attempts')->insertGetId(['order_id'=>$o->id,'gateway'=>'disabled','amount'=>$o->total,'status'=>'failed','created_at'=>now(),'updated_at'=>now()]);$this->store->settle($id,['status'=>'unknown']);$this->assertDatabaseHas('orders',['id'=>$o->id,'payment_status'=>'paid']);
 }
}
